<?php require '../includes/bootstrap.php';student_required();$sid=$_SESSION['student_id'];if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['create'])){try{$pdo->beginTransaction();$chk=$pdo->prepare('SELECT 1 FROM team_members WHERE student_id=?');$chk->execute([$sid]);if($chk->fetch())throw new Exception('You already belong to a team.');$pdo->prepare('INSERT INTO teams(event_id,team_name,leader_id) VALUES(?,?,?)')->execute([(int)$_POST['event_id'],trim($_POST['team_name']),$sid]);$tid=$pdo->lastInsertId();$pdo->prepare('INSERT INTO team_members(team_id,student_id) VALUES(?,?)')->execute([$tid,$sid]);$pdo->commit();flash('success','Team created.');redirect('team.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}}if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['add_member'])){$app=trim($_POST['application_no']);$teamId=(int)$_POST['team_id'];$lead=$pdo->prepare('SELECT 1 FROM teams WHERE team_id=? AND leader_id=?');$lead->execute([$teamId,$sid]);if(!$lead->fetch()){flash('error','Only the team leader can add members.');redirect('team.php');}$u=$pdo->prepare('SELECT student_id FROM students WHERE application_no=?');$u->execute([$app]);$mid=$u->fetchColumn();if(!$mid){flash('error','Student not found.');redirect('team.php');}try{$pdo->prepare('INSERT INTO team_members(team_id,student_id) VALUES(?,?)')->execute([$teamId,$mid]);flash('success','Member added.');}catch(Throwable $e){flash('error','Student may already belong to this team.');}redirect('team.php');}$t=$pdo->prepare('SELECT t.*,e.event_name FROM team_members tm JOIN teams t ON t.team_id=tm.team_id JOIN events e ON e.event_id=t.event_id WHERE tm.student_id=? LIMIT 1');$t->execute([$sid]);$team=$t->fetch();$events=$pdo->query("SELECT event_id,event_name FROM events WHERE status IN ('OPEN','UPCOMING') ORDER BY start_date")->fetchAll();$members=[];if($team){$m=$pdo->prepare('SELECT s.student_id,s.name,s.application_no,s.branch FROM team_members tm JOIN students s ON s.student_id=tm.student_id WHERE tm.team_id=?');$m->execute([$team['team_id']]);$members=$m->fetchAll();}$title='My Team';$base='../';$nav='<a href="dashboard.php">Dashboard</a><a href="problems.php">Problems</a><a href="history.php">History</a><a href="../logout.php">Logout</a>';include '../includes/header.php';?><h1>My Team</h1><?php if(!$team):?><div class="card form"><h3>Create a team</h3><form method="post"><input type="hidden" name="create" value="1"><label>Team Name</label><input name="team_name" required><label>Event</label><select name="event_id" required><?php foreach($events as $e):?><option value="<?=e($e['event_id'])?>"><?=e($e['event_name'])?></option><?php endforeach;?></select><div class="actions"><button class="btn">Create Team</button></div></form></div><?php else:?><div class="card"><span class="badge"><?=e($team['event_name'])?></span><h2><?=e($team['team_name'])?></h2><table class="table"><tr><th>Name</th><th>Application</th><th>Branch</th><th>Role</th></tr><?php foreach($members as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['application_no'])?></td><td><?=e($m['branch'])?></td><td><?=$m['student_id']==$team['leader_id']?'Leader':'Member'?></td></tr><?php endforeach;?></table><?php if($sid==$team['leader_id']):?><form method="post"><input type="hidden" name="add_member" value="1"><input type="hidden" name="team_id" value="<?=e($team['team_id'])?>"><label>Add member by application number</label><div class="row"><input name="application_no" required><button class="btn">Add</button></div></form><?php endif;?></div><?php endif;?><?php include '../includes/footer.php';?>
